function (s) {
        return String(s)
            .replace(/\\/g, "\\\\")
            .replace(/"/g, "\\\"")
            .replace(/\r/g, "\\r")
            .replace(/\n/g, "\\n")
            .replace(/\t/g, "\\t")
            .replace(/[\x00-\x1f]/g, function (ch) {
                // CR/LF/TAB above retain their existing short escape spelling.
                var hex = ch.charCodeAt(0).toString(16);
                return "\\u" + ("0000" + hex).slice(-4);
            });
    }

function (obj) {
        var parts = [];
        var k;
        for (k in obj) {
            if (!obj.hasOwnProperty(k)) {
                continue;
            }
            if (typeof obj[k] === "number") {
                parts[parts.length] = "\"" + AEToolbox.jsonEscape(k) + "\":" + obj[k];
            } else if (typeof obj[k] === "boolean") {
                parts[parts.length] = "\"" + AEToolbox.jsonEscape(k) + "\":" + (obj[k] ? "true" : "false");
            } else {
                parts[parts.length] = "\"" + AEToolbox.jsonEscape(k) + "\":\"" + AEToolbox.jsonEscape(obj[k]) + "\"";
            }
        }
        return "{" + parts.join(",") + "}";
    }

function (value) {
        var parts = [];
        var k;
        var i;

        if (value === null || typeof value === "undefined") {
            return "null";
        }
        if (typeof value === "number") {
            return isFinite(value) ? String(value) : "0";
        }
        if (typeof value === "boolean") {
            return value ? "true" : "false";
        }
        if (typeof value === "string") {
            return "\"" + AEToolbox.jsonEscape(value) + "\"";
        }
        if (value instanceof Array) {
            for (i = 0; i < value.length; i++) {
                parts[parts.length] = AEToolbox.stringify(value[i]);
            }
            return "[" + parts.join(",") + "]";
        }
        if (typeof value === "object") {
            for (k in value) {
                if (value.hasOwnProperty(k) && typeof value[k] !== "function" && k.charAt(0) !== "_") {
                    parts[parts.length] = "\"" + AEToolbox.jsonEscape(k) + "\":" + AEToolbox.stringify(value[k]);
                }
            }
            return "{" + parts.join(",") + "}";
        }
        return "\"\"";
    }
